"use client"; import { PageShell } from "../../components/layout/PageShell"; import { Card } from "../../components/ui/Card"; import { Badge } from "../../components/ui/Badge"; import { Button } from "../../components/ui/Button"; import { Countdown } from "../../components/ui/Countdown"; import { useTasks } from "../../lib/hooks/useBlobbyApi"; export default function Tasks(){const q=useTasks(); const tasks=(q.data as any[])||[]; return <PageShell eyebrow="Airdrop" title="Tasks & rewards" intro="One-time and daily tasks with API, auto, proof, and manual review states."><div className="mb-6"><Badge>Daily reset <Countdown target={new Date(Date.now()+12*3600000)}/></Badge></div><div className="grid gap-4 md:grid-cols-2">{tasks.map(t=><Card key={t.id}><h2 className="display-text text-2xl">{t.title}</h2><Badge className="mt-3">{t.status}</Badge><p className="mt-3">Reward: {t.reward}</p><Button className="mt-4">Claim</Button></Card>)}</div></PageShell>}
